    public static int lengthOfLongestSubstring(String s) {
        if(s.isEmpty()){
            return 0;
        }
        var max = Integer.MIN_VALUE;
        var arr = s.toCharArray();
        var block = false;
        for (int i = 0; i < arr.length; i++) {
            var setChar = new HashSet<Character>();
            for(int j=i; j<arr.length && !block; j++){
                if(setChar.contains(arr[j])){
                    if(max<setChar.size()){
                        max = setChar.size();
                    }
                    setChar = new HashSet<>();
                    setChar.add(arr[j]);
                    block = true;
                }else{
                    setChar.add(arr[j]);
                }
            }
            block = false;
            if(!setChar.isEmpty()){
                if(max<setChar.size()){
                    max = setChar.size();
                }
            }
        }
        return max;
    }

